/* Aracne V4 · multi-trip hub, server alerts and snapshots. */
'use strict';
(()=>{
 const api=window.aracneShared;if(!api?._getRaw)return;
 const locales=['fr','it','en','es'],c=Math.max(0,locales.indexOf(document.documentElement.lang));
 const copy={
  hub:['Mes voyages','I miei viaggi','My trips','Mis viajes'],current:['Voyage actuel','Viaggio attuale','Current trip','Viaje actual'],newTrip:['Nouveau voyage','Nuovo viaggio','New trip','Nuevo viaje'],rename:['Renommer le voyage','Rinomina il viaggio','Rename trip','Renombrar viaje'],saveVersion:['Créer une sauvegarde','Crea un salvataggio','Create snapshot','Crear copia'],versions:['Sauvegardes','Salvataggi','Snapshots','Copias'],shareEdit:['Inviter à modifier','Invita a modificare','Invite to edit','Invitar a editar'],shareRead:['Partager en lecture','Condividi in lettura','Share view-only','Compartir lectura'],more:['Plus d’options de partage','Altre opzioni di condivisione','More sharing options','Más opciones'],owner:['Organisateur','Organizzatore','Organiser','Organizador'],edit:['Participant · modification','Partecipante · modifica','Participant · edit','Participante · edición'],read:['Lecture seule','Sola lettura','View only','Solo lectura'],updated:['Le voyage commun a été mis à jour','Il viaggio condiviso è stato aggiornato','The shared trip was updated','El viaje compartido se actualizó'],changes:['nouvelles modifications','nuove modifiche','new changes','nuevos cambios'],whatsapp:['Partager l’alerte sur WhatsApp','Condividi avviso su WhatsApp','Share alert on WhatsApp','Compartir alerta por WhatsApp'],switched:['Voyage chargé','Viaggio caricato','Trip loaded','Viaje cargado'],snapshotLabel:['Nom de cette sauvegarde (facultatif)','Nome del salvataggio (facoltativo)','Snapshot label (optional)','Nombre de la copia (opcional)'],saved:['Sauvegarde créée','Salvataggio creato','Snapshot created','Copia creada'],restored:['Sauvegarde restaurée','Salvataggio ripristinato','Snapshot restored','Copia restaurada'],restore:['Restaurer','Ripristina','Restore','Restaurar'],confirmRestore:['Restaurer cette version pour tout le groupe ?','Ripristinare questa versione per tutto il gruppo?','Restore this version for the whole group?','¿Restaurar esta versión para todo el grupo?'],empty:['Aucun autre voyage enregistré sur cet appareil.','Nessun altro viaggio salvato su questo dispositivo.','No other trip saved on this device.','No hay otros viajes guardados en este dispositivo.'],server:['Répertoire organisateur','Archivio organizzatore','Organiser directory','Directorio del organizador']
 };
 const t=k=>copy[k]?.[c]||copy[k]?.[0]||k;
 const esc4=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
 const KEY='sb_publishable_heDZcO0ymf5N0SbnaYBT4w_v-ItZm8S';
 const WS_ENDPOINT='https://cpnjdyhsepytphwlenbg.supabase.co/rest/v1/rpc/aracne_workspace';
 const WORKSPACE='aracne-workspace-v4',LIB='aracne-trip-library-v4';
 const legacyOpen=api.open;let lastAlert=[];
 function actorName(){const s=api._getRaw();try{return localStorage.getItem('aracne-collab-name-'+(s?.id||'local'))?.trim()||(s?.role==='owner'?t('owner'):'Participant')}catch{return s?.role==='owner'?t('owner'):'Participant'}}
 window.aracneSharedActor=actorName;
 function loadLibrary(){try{return JSON.parse(localStorage.getItem(LIB)||'[]')}catch{return []}}
 function saveLibrary(rows){try{localStorage.setItem(LIB,JSON.stringify(rows.slice(0,30)))}catch{}}
 function compactSession(s){if(!s?.id)return null;return {id:s.id,token:s.token||null,edit:s.edit||null,read:s.read||null,role:s.role||'read',name:s.name||s.base?.name||state.name||'Voyage',workspaceId:s.workspaceId||null,workspaceToken:s.workspaceToken||null,revision:s.revision||0,lastEvent:s.lastEvent||0,updatedAt:new Date().toISOString()}}
 function upsertLibrary(s=api._getRaw()){const row=compactSession(s);if(!row)return;const rows=loadLibrary().filter(x=>x.id!==row.id);rows.unshift(row);saveLibrary(rows)}
 function savePrivate(id){if(!id)return;try{localStorage.setItem('aracne-private-'+id,JSON.stringify((state.notes||[]).filter(n=>n.privacy==='private')))}catch{}}
 function loadPrivate(id){try{return JSON.parse(localStorage.getItem('aracne-private-'+id)||'[]')}catch{return []}}
 async function post(url,body){const r=await fetch(url,{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw Error('offline');const data=await r.json();if(data.error)throw Error(data.error);return data}
 async function workspaceRpc(action,extra={},credentials=window.aracneWorkspaceV4){return post(WS_ENDPOINT,{p_action:action,p_id:credentials?.id||null,p_token:credentials?.token||null,...extra})}
 async function ensureWorkspace(){let w=null;try{w=JSON.parse(localStorage.getItem(WORKSPACE)||'null')}catch{}if(!w?.id||!w?.token){const token=api._secret(),created=await workspaceRpc('create',{}, {token});w={id:created.id,token};try{localStorage.setItem(WORKSPACE,JSON.stringify(w))}catch{}}window.aracneWorkspaceV4=w;return w}
 async function attachOwner(){const s=api._getRaw();if(!s||s.role!=='owner')return;const w=await ensureWorkspace();if(s.token)try{await workspaceRpc('attach',{p_trip_id:s.id,p_trip_token:s.token},w)}catch{}s.workspaceId=w.id;s.workspaceToken=w.token;api._setRaw(s);upsertLibrary(s)}
 function roleLabel(role){return t(role==='owner'?'owner':role==='edit'?'edit':'read')}
 function tripLink(token,id=api._getRaw()?.id){const u=new URL(location.href);u.search='';u.hash='trip='+id+'&key='+token;return u.href}
 async function shareUrl(url,title){if(navigator.share)try{await navigator.share({title,text:title,url});return}catch(e){if(e?.name==='AbortError')return}try{await navigator.clipboard.writeText(url);toast('Lien copié')}catch{prompt('Lien',url)}}
 async function ensureInviteSecrets(){const s=api._getRaw();if(!s||s.role!=='owner')return s;if(s.edit&&s.read)return s;const edit=api._secret(),read=api._secret();await api._rpc('rotate',{p_edit:edit,p_read:read});s.edit=edit;s.read=read;api._setRaw(s);upsertLibrary(s);return s}
 function alertBadge(count){let b=document.querySelector('.v4AlertBadge'),j=document.querySelector('nav [data-view="journal"]');if(!j)return;if(!b){b=document.createElement('span');b.className='v4AlertBadge';j.append(b)}b.textContent=String(count);b.hidden=!count}
 window.aracneSharedV4Events=events=>{if(!events?.length)return;lastAlert=events;const me=actorName(),external=events.filter(e=>e.actor!==me);if(!external.length)return;alertBadge(external.length);const e=external.at(-1),msg=(e.actor||'Participant')+' '+(e.action||'a modifié le voyage')+(e.detail?' · '+e.detail:'');toast(t('updated')+' · '+msg);const bar=document.querySelector('.sharedBar');if(bar){let a=document.querySelector('#v4AlertAction');if(!a){a=document.createElement('button');a.id='v4AlertAction';a.type='button';a.className='textBtn';bar.append(a)}a.textContent=external.length+' '+t('changes');a.onclick=()=>{alertBadge(0);show('journal')}}};
 async function switchTrip(entry){const current=api._getRaw();savePrivate(current?.id);api._backup();const workspace=window.aracneWorkspaceV4;const candidate={id:entry.id,token:entry.token||null,role:entry.role||'owner',workspaceId:entry.workspaceId||workspace?.id||null,workspaceToken:entry.workspaceToken||workspace?.token||null};const r=await api._rpc('read',{p_since_event:entry.lastEvent||0},candidate);state.notes=loadPrivate(entry.id);candidate.role=r.role;candidate.revision=r.revision;candidate.name=r.name||r.document.name;candidate.lastEvent=Number(r.last_event)||0;candidate.base=JSON.parse(JSON.stringify(r.document));api._setRaw(candidate);api._apply(r.document);upsertLibrary(candidate);document.querySelector('#modal')?.close();toast(t('switched')+' · '+candidate.name);show('plan')}
 async function openLibrary(){const local=loadLibrary(),workspace=await ensureWorkspace().catch(()=>null);let server=[];if(workspace)try{server=(await workspaceRpc('list',{},workspace)).trips||[]}catch{}const byId=new Map(local.map(x=>[x.id,x]));server.forEach(x=>{const old=byId.get(x.id)||{};byId.set(x.id,{...old,...x,role:'owner',workspaceId:workspace?.id,workspaceToken:workspace?.token})});const rows=[...byId.values()].sort((a,b)=>String(b.updated_at||b.updatedAt||'').localeCompare(String(a.updated_at||a.updatedAt||'')));dialog(t('hub'),'<div class="v4LibraryHead"><p>'+esc4(t('server'))+'</p><button class="primary" id="v4NewTrip">＋ '+esc4(t('newTrip'))+'</button></div><div class="v4TripList">'+(rows.length?rows.map(x=>'<button class="v4TripCard '+(x.id===api._getRaw()?.id?'active':'')+'" data-trip-id="'+esc4(x.id)+'"><span><b>'+esc4(x.name||'Voyage')+'</b><small>'+esc4(roleLabel(x.role))+' · #'+(Number(x.revision)||0)+'</small></span><span>›</span></button>').join(''):'<div class="empty">'+esc4(t('empty'))+'</div>')+'</div>');document.querySelector('#v4NewTrip').onclick=()=>{const s=api._getRaw();savePrivate(s?.id);api._backup();api._setRaw(null);state=defaults();state.journal=[];try{localStorage.setItem('aracne-puglia-v1',JSON.stringify(state))}catch{}location.reload()};document.querySelectorAll('[data-trip-id]').forEach(b=>b.onclick=()=>switchTrip(byId.get(b.dataset.tripId)).catch(()=>toast('Impossible de charger ce voyage')))}
 async function renameTrip(){const s=api._getRaw();if(!s||s.role!=='owner')return;const name=prompt(t('rename'),s.name||state.name||'');if(!name?.trim())return;const r=await api._rpc('rename',{p_name:name.trim(),p_actor:actorName()});state.name=r.name;s.name=r.name;s.revision=r.revision;if(s.base)s.base.name=r.name;api._setRaw(s);upsertLibrary(s);fillForm();if(view==='plan')renderPlan();toast(r.name)}
 async function snapshot(){const s=api._getRaw();if(!s||s.role!=='owner')return;const label=prompt(t('snapshotLabel'),'')||null;await api._rpc('snapshot',{p_actor:actorName(),p_label:label});toast(t('saved'))}
 async function versions(){const s=api._getRaw();if(!s)return;const r=await api._rpc('versions');dialog(t('versions'),'<div class="v4VersionList">'+((r.versions||[]).map(v=>'<article><div><b>'+esc4(v.label||v.name)+'</b><small>#'+v.revision+' · '+esc4(new Date(v.created_at).toLocaleString(document.documentElement.lang))+' · '+esc4(v.actor||'')+'</small></div>'+(s.role==='owner'?'<button class="secondary" data-restore="'+v.id+'">'+esc4(t('restore'))+'</button>':'')+'</article>').join('')||'<div class="empty">'+esc4(t('empty'))+'</div>')+'</div>');document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{if(!confirm(t('confirmRestore')))return;const rr=await api._rpc('restore',{p_version_id:Number(b.dataset.restore),p_actor:actorName()});s.revision=rr.revision;s.name=rr.name;s.base=JSON.parse(JSON.stringify(rr.document));api._setRaw(s);state.notes=loadPrivate(s.id);api._apply(rr.document);upsertLibrary(s);document.querySelector('#modal').close();toast(t('restored'))})}
 async function openHub(){const s=api._getRaw();upsertLibrary(s);const canOwner=s?.role==='owner',hasAlert=lastAlert.length;let html='<div class="v4Current"><span class="eyebrow">'+esc4(t('current'))+'</span><h3>'+esc4(s?.name||state.name||'Voyage')+'</h3><p>'+esc4(s?roleLabel(s.role):'Local')+(s?' · #'+(s.revision||0):'')+'</p></div><div class="v4HubGrid"><button class="secondary" id="v4Trips">'+esc4(t('hub'))+'</button>';if(canOwner)html+='<button class="secondary" id="v4Rename">'+esc4(t('rename'))+'</button><button class="secondary" id="v4Snapshot">'+esc4(t('saveVersion'))+'</button>';if(s)html+='<button class="secondary" id="v4Versions">'+esc4(t('versions'))+'</button>';if(canOwner)html+='<button class="secondary" id="v4Edit">'+esc4(t('shareEdit'))+'</button><button class="secondary" id="v4Read">'+esc4(t('shareRead'))+'</button>';if(hasAlert)html+='<button class="secondary" id="v4WhatsApp">'+esc4(t('whatsapp'))+'</button>';html+='<button class="textBtn" id="v4More">'+esc4(t('more'))+'</button></div>';dialog(t('hub'),html);document.querySelector('#v4Trips').onclick=openLibrary;document.querySelector('#v4Rename')?.addEventListener('click',()=>renameTrip().catch(()=>toast('Erreur')));document.querySelector('#v4Snapshot')?.addEventListener('click',()=>snapshot().catch(()=>toast('Erreur')));document.querySelector('#v4Versions')?.addEventListener('click',()=>versions().catch(()=>toast('Erreur')));document.querySelector('#v4Edit')?.addEventListener('click',async()=>{const x=await ensureInviteSecrets();shareUrl(tripLink(x.edit),x.name||state.name)});document.querySelector('#v4Read')?.addEventListener('click',async()=>{const x=await ensureInviteSecrets();shareUrl(tripLink(x.read),x.name||state.name)});document.querySelector('#v4WhatsApp')?.addEventListener('click',()=>{const lines=lastAlert.slice(-6).map(e=>'• '+e.actor+': '+e.action+(e.detail?' — '+e.detail:'')).join('\n');open('https://wa.me/?text='+encodeURIComponent((s?.name||state.name)+'\n'+lines),'_blank','noopener')});document.querySelector('#v4More').onclick=legacyOpen}
 api.open=openHub;
 const top=document.querySelector('.sharedBar');if(top){const trips=document.createElement('button');trips.type='button';trips.className='textBtn v4TripsShortcut';trips.textContent=t('hub');trips.onclick=openLibrary;top.append(trips)}
 (async()=>{const s=api._getRaw();if(s){s.name=s.name||s.base?.name||state.name;api._setRaw(s);upsertLibrary(s);if(s.role==='owner')await attachOwner().catch(()=>{})}else await ensureWorkspace().catch(()=>{})})();
})();